import{_ as a,o as i,c as l,ag as e}from"./chunks/framework.ePeAWSvT.js";const r="/images/internal-01.png",o="/images/internal-02.png",s="/images/internal-03.png",n="/images/internal-04.png",g=JSON.parse('{"title":"手机内录","description":"","frontmatter":{},"headers":[],"relativePath":"voice/internal.md","filePath":"voice/internal.md","lastUpdated":null}'),d={name:"voice/internal.md"};function c(p,t,h,u,m,_){return i(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="手机内录" tabindex="-1">手机内录 <a class="header-anchor" href="#手机内录" aria-label="Permalink to &quot;手机内录&quot;">​</a></h1><blockquote><p>手机内录，边听边记，一气呵成！</p></blockquote><p>自动捕获手机播放的声音，AI同步转写文字，让你在听的同时就把重点内容记下来。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li><strong>线上学习</strong>：线上直播课程、讲座内容轻松记录</li><li><strong>视频记录</strong>：生成视频逐字稿 + 要点总结</li><li><strong>播客整理</strong>：语音+文字双轨保存，随时回顾不遗漏</li><li><strong>区分说话人</strong>：多个说话人，可以自动区分每个说话人内容</li></ul><div class="warning custom-block"><p class="custom-block-title">不适用的场景</p><ul><li>录制拨打电话、语音通话、微信 QQ 通话</li><li>腾讯/飞书/钉钉会议等场景</li><li>带耳机等外部播放设备时也无法正常录制</li></ul></div><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><ol><li>打开 APP，点击首页底部「录音」按钮，选择「手机内录」</li><li>同意 Get 笔记使用手机录屏权限，然后点击红色按钮&quot;开始录制&quot;</li><li>去其他 APP 打开你想录制的内容（如播客、B站直播等）开始播放</li><li>回到 Get 笔记 APP 后，录制页面会有实时转录的文字展示出来</li><li>录制结束后，AI 会自动对音频转写并总结整理</li></ol><div class="tip custom-block"><p class="custom-block-title">特别说明</p><p>手机内录仅通过手机内部声音进行转写，不会录制你的手机屏幕和保存任何视频。</p></div><h2 id="录制时长" tabindex="-1">录制时长 <a class="header-anchor" href="#录制时长" aria-label="Permalink to &quot;录制时长&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用户类型</th><th>单次时长</th><th>次数限制</th></tr></thead><tbody><tr><td>普通用户</td><td>1 小时</td><td>不限</td></tr><tr><td>会员用户</td><td>3 小时</td><td>不限</td></tr></tbody></table><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;padding:10px 0;"><img src="'+r+'" alt="手机内录入口" style="width:180px;border-radius:8px;"><img src="'+o+'" alt="开始录制" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="录制中" style="width:180px;border-radius:8px;"><img src="'+n+'" alt="转写结果" style="width:180px;border-radius:8px;"></div>',13)])])}const x=a(d,[["render",c]]);export{g as __pageData,x as default};
